#pragma once

// Reference venue: a synthetic MDP 3.0–shaped venue used to develop and test
// the core end-to-end without a real venue's schema or captures.
//
// The field layouts below mirror venues/ref/schema.xml exactly. In production
// this whole file is replaced by:
//   - venues/<venue>/gen/**        generated by the SBE tool from schema.xml
//   - venues/<venue>/policy.hpp    the VenuePolicy constants
// and the hand-written decoders here go away. They exist so Phases 3–7 can be
// built and tested before any venue hands over a schema.
//
// NOTE: unlike generated codecs, these decoders are NOT version-tolerant — they
// do not use actingBlockLength to treat trailing fields as absent on an older
// schema version. That tolerance is one of the main reasons to generate.

#include <cstdint>
#include <expected>
#include <string_view>

#include "rfeed/byte_reader.hpp"
#include "rfeed/messages.hpp"
#include "rfeed/types.hpp"
#include "rfeed/venue.hpp"

namespace rfeed::venue_ref {

// Template IDs live here and nowhere else. The core only ever sees
// LogicalMessage, so a venue that numbers these differently costs one edit.
inline constexpr std::uint16_t kTplChannelReset    = 4;
inline constexpr std::uint16_t kTplHeartbeat       = 12;
inline constexpr std::uint16_t kTplSecurityStatus  = 30;
inline constexpr std::uint16_t kTplIncrementalBook = 46;
inline constexpr std::uint16_t kTplSnapshot        = 52;
inline constexpr std::uint16_t kTplInstrumentDef   = 54;

// Root block lengths, in bytes, as published in schema.xml.
inline constexpr std::uint16_t kBlkChannelReset      = 12;
inline constexpr std::uint16_t kBlkSecurityStatus    = 16;
inline constexpr std::uint16_t kBlkIncremental       = 9;
inline constexpr std::uint16_t kBlkSnapshot          = 26;
inline constexpr std::uint16_t kBlkInstrumentDef     = 40;
inline constexpr std::uint16_t kBlkMdEntry           = 32;
inline constexpr std::uint16_t kBlkSnapshotEntry     = 24;

// Wire encodings. EntryType follows the FIX convention of ASCII codes.
inline constexpr std::uint8_t kEntryBid          = '0';
inline constexpr std::uint8_t kEntryOffer        = '1';
inline constexpr std::uint8_t kEntryTrade        = '2';
inline constexpr std::uint8_t kEntryImpliedBid   = 'E';
inline constexpr std::uint8_t kEntryImpliedOffer = 'F';

inline constexpr std::uint8_t kStatusHalted = 2;
inline constexpr std::uint8_t kStatusClosed = 4;
inline constexpr std::uint8_t kStatusOpen   = 17;
inline constexpr std::uint8_t kStatusPaused = 18;
inline constexpr std::uint8_t kStatusPreOpen = 21;

inline constexpr std::uint8_t kEventEndOfEventBit = 0x01;

[[nodiscard]] constexpr EntryType to_entry_type(std::uint8_t raw) noexcept {
  switch (raw) {
    case kEntryBid:          return EntryType::Bid;
    case kEntryOffer:        return EntryType::Offer;
    case kEntryTrade:        return EntryType::Trade;
    case kEntryImpliedBid:   return EntryType::ImpliedBid;
    case kEntryImpliedOffer: return EntryType::ImpliedOffer;
    default:                 return EntryType::Unknown;
  }
}

[[nodiscard]] constexpr UpdateAction to_update_action(std::uint8_t raw) noexcept {
  switch (raw) {
    case 0:  return UpdateAction::New;
    case 1:  return UpdateAction::Change;
    case 2:  return UpdateAction::Delete;
    case 3:  return UpdateAction::DeleteThru;
    case 4:  return UpdateAction::DeleteFrom;
    case 5:  return UpdateAction::Overlay;
    default: return UpdateAction::Unknown;
  }
}

[[nodiscard]] constexpr TradingStatus to_trading_status(std::uint8_t raw) noexcept {
  switch (raw) {
    case kStatusHalted:  return TradingStatus::Halted;
    case kStatusClosed:  return TradingStatus::Closed;
    case kStatusOpen:    return TradingStatus::Open;
    case kStatusPaused:  return TradingStatus::Paused;
    case kStatusPreOpen: return TradingStatus::PreOpen;
    default:             return TradingStatus::Unknown;
  }
}

// Field-level decoders. Each takes a reader already bounded to the block it is
// decoding, so an over-read fails rather than straying into the next block.
struct RefCodec {
  [[nodiscard]] static std::expected<IncrementalHeader, DecodeError> incremental_header(
      ByteReader& in) noexcept;
  [[nodiscard]] static std::expected<MdEntry, DecodeError> md_entry(ByteReader& in) noexcept;
  [[nodiscard]] static std::expected<SnapshotHeader, DecodeError> snapshot_header(
      ByteReader& in) noexcept;
  [[nodiscard]] static std::expected<SnapshotEntry, DecodeError> snapshot_entry(
      ByteReader& in) noexcept;
  [[nodiscard]] static std::expected<InstrumentDefinition, DecodeError> instrument_definition(
      ByteReader& in) noexcept;
  [[nodiscard]] static std::expected<SecurityStatusMsg, DecodeError> security_status(
      ByteReader& in) noexcept;
  [[nodiscard]] static std::expected<ChannelResetMsg, DecodeError> channel_reset(
      ByteReader& in) noexcept;
};

struct RefVenue : VenueDefaults {
  using Codec = RefCodec;

  static constexpr std::string_view kName = "ref";
  static constexpr std::uint16_t    kSchemaId = 1;
  static constexpr std::uint16_t    kMinSupportedVersion = 13;
  static constexpr std::size_t      kGroupCountBytes = 1;  // uint8 numInGroup, as CME
  static constexpr bool             kHeartbeatConsumesSeqNum = false;
  static constexpr bool             kSecurityIdStableAcrossPeriods = false;

  static constexpr LogicalMessage classify(std::uint16_t template_id) noexcept {
    switch (template_id) {
      case kTplChannelReset:    return LogicalMessage::ChannelReset;
      case kTplHeartbeat:       return LogicalMessage::Heartbeat;
      case kTplSecurityStatus:  return LogicalMessage::SecurityStatus;
      case kTplIncrementalBook: return LogicalMessage::IncrementalBook;
      case kTplSnapshot:        return LogicalMessage::SnapshotFullRefresh;
      case kTplInstrumentDef:   return LogicalMessage::InstrumentDefinition;
      default:                  return LogicalMessage::Unknown;
    }
  }
};

static_assert(VenuePolicy<RefVenue>);

}  // namespace rfeed::venue_ref
